  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Rilský klášter', 'Největší a nejposvátnější klášter Bulharska s pruhovanými arkádami a freskami, UNESCO památka. Duchovní srdce země ukryté v horách.', 42.1333, 23.34, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rila_Monastery.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rila_Monastery.jpg"}'::text[], 0),
    (v_route, 'Maljovica', 'Horské středisko pod skalnatými štíty Rily, výchozí bod k jezerům a vrcholům. Ráj horských scenérií.', 42.1789, 23.3556, 'https://commons.wikimedia.org/wiki/Special:FilePath/Malyovitsa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Malyovitsa.jpg"}'::text[], 1),
    (v_route, 'Sedm rilských jezer', 'Skupina ledovcových jezer v nejvyšších partiích Rily, jeden z nejkrásnějších přírodních útvarů Balkánu. Ikonická scenérie.', 42.21, 23.32, 'https://commons.wikimedia.org/wiki/Special:FilePath/Seven_Rila_Lakes.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Seven_Rila_Lakes.jpg"}'::text[], 2),
    (v_route, 'Stob – pyramidy', 'Bizarní erozní věže z červené horniny nad vesnicí Stob u Rily. Ojedinělý geologický úkaz.', 42.15, 23.13, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stob_Pyramids.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stob_Pyramids.jpg"}'::text[], 3),
    (v_route, 'Jeskyně Svatého Ivana', 'Poustevnická jeskyně zakladatele kláštera Ivana Rilského nedaleko areálu. Poutní zastávka.', 42.13, 23.3556, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rila_Monastery.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rila_Monastery.jpg"}'::text[], 4);
