  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Bansko', 'Horské středisko pod štíty Pirinu s kamennou architekturou a živou mehanou. Brána do národního parku.', 41.8375, 23.4881, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bansko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bansko.jpg"}'::text[], 0),
    (v_route, 'Melnik', 'Nejmenší město Bulharska ukryté mezi pískovcovými pyramidami, proslulé silným vínem. Půvabná zastávka mimo čas.', 41.5228, 23.3931, 'https://commons.wikimedia.org/wiki/Special:FilePath/Melnik.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Melnik.jpg"}'::text[], 1),
    (v_route, 'Melnické pyramidy', 'Bizarní pískovcové věže obklopující městečko, výtvor eroze. Ojedinělá scenérie jihu.', 41.525, 23.4, 'https://commons.wikimedia.org/wiki/Special:FilePath/Melnik_Pyramids.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Melnik_Pyramids.jpg"}'::text[], 2),
    (v_route, 'Rožen – klášter', 'Největší středověký klášter v Pirinu s freskami a vinicemi v okolí. Klidná zastávka nad pyramidami.', 41.5306, 23.4297, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rozhen_Monastery.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rozhen_Monastery.jpg"}'::text[], 3),
    (v_route, 'Národní park Pirin', 'Divoké pohoří s ledovcovými jezery a starými borovicemi, UNESCO památka. Ráj horské přírody.', 41.73, 23.46, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pirin_National_Park.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pirin_National_Park.jpg"}'::text[], 4);
