  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Soutěska Trigrad', 'Dramatická skalní soutěska s kolmými stěnami a jeskyní Ďáblovo hrdlo, kam podle legendy sestoupil Orfeus. Nejtajemnější místo Rodop.', 41.6144, 24.3789, 'https://commons.wikimedia.org/wiki/Special:FilePath/Trigrad_Gorge.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Trigrad_Gorge.jpg"}'::text[], 0),
    (v_route, 'Smoljan', 'Horské město roztažené v údolí pod nejvyššími štíty Rodop, výchozí bod do hor. Brána do divokého kraje.', 41.5764, 24.7106, 'https://commons.wikimedia.org/wiki/Special:FilePath/Smolyan.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Smolyan.jpg"}'::text[], 1),
    (v_route, 'Devín', 'Lázeňské městečko proslulé minerální vodou v hlubokém říčním údolí. Osvěžující zastávka mezi horami.', 41.7431, 24.4, 'https://commons.wikimedia.org/wiki/Special:FilePath/Devin.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Devin.jpg"}'::text[], 2),
    (v_route, 'Ďáblovo hrdlo', 'Podzemní jeskyně s hučícím vodopádem, kde řeka mizí ve skále. Legendární brána do podsvětí.', 41.6144, 24.3789, 'https://commons.wikimedia.org/wiki/Special:FilePath/Devil%27s_Throat_Cave.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Devil%27s_Throat_Cave.jpg"}'::text[], 3),
    (v_route, 'Vesnice Široka Laka', 'Malebná horská vesnice s kamennou architekturou a školou lidové hudby. Ukázka rodopské kultury.', 41.63, 24.55, 'https://commons.wikimedia.org/wiki/Special:FilePath/Shiroka_Laka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Shiroka_Laka.jpg"}'::text[], 4);
