  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Chrám Šipka', 'Zlatě zdobený ruský pravoslavný chrám na úpatí průsmyku, památník padlým v osvobozenecké válce. Nejfotogeničtější kostel Bulharska.', 42.7194, 25.32, 'https://commons.wikimedia.org/wiki/Special:FilePath/Shipka_Memorial_Church.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Shipka_Memorial_Church.jpg"}'::text[], 0),
    (v_route, 'Památník svobody na Šipce', 'Kamenná věž na vrcholu průsmyku připomínající obranu proti Osmanům. Ikona bulharské nezávislosti a daleké výhledy.', 42.7458, 25.3306, 'https://commons.wikimedia.org/wiki/Special:FilePath/Shipka_Monument.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Shipka_Monument.jpg"}'::text[], 1),
    (v_route, 'Pomník Buzludža', 'Monumentální opuštěný komunistický památník ve tvaru UFO na vrcholu hory. Surreální kulisa a symbol minulé éry.', 42.7357, 25.3931, 'https://commons.wikimedia.org/wiki/Special:FilePath/Buzludzha.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Buzludzha.jpg"}'::text[], 2),
    (v_route, 'Kazanlak – Údolí růží', 'Město uprostřed proslulého Údolí růží s thráckou hrobkou UNESCO. Voňavá zastávka pod horami.', 42.6178, 25.3936, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kazanlak.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kazanlak.jpg"}'::text[], 3),
    (v_route, 'Etar – skanzen', 'Živý skanzen řemesel s vodními mlýny a dílnami u Gabrova. Ukázka bulharské tradice.', 42.83, 25.32, 'https://commons.wikimedia.org/wiki/Special:FilePath/Etar.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Etar.jpg"}'::text[], 4);
