  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Pevnost Carevec', 'Mohutná středověká pevnost na kopci nad meandrem Jantry, sídlo bulharských carů. Nejpůsobivější hrad země.', 43.0817, 25.6558, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tsarevets.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tsarevets.jpg"}'::text[], 0),
    (v_route, 'Staré město Veliko Tarnovo', 'Malebné domy nalepené na strmém svahu nad řekou s řemeslnou ulicí Samovodska čaršija. Srdce bývalé metropole.', 43.0813, 25.655, 'https://commons.wikimedia.org/wiki/Special:FilePath/Veliko_Tarnovo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Veliko_Tarnovo.jpg"}'::text[], 1),
    (v_route, 'Arbanasi', 'Vesnice nad městem s kamennými domy-pevnostmi a kostely plnými fresek. Klidná zastávka s výhledem.', 43.0778, 25.67, 'https://commons.wikimedia.org/wiki/Special:FilePath/Arbanasi.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Arbanasi.jpg"}'::text[], 2),
    (v_route, 'Preobraženský klášter', 'Největší klášter regionu zavěšený pod skalami severně od města. Freskami zdobený klenot.', 43.11, 25.65, 'https://commons.wikimedia.org/wiki/Special:FilePath/Preobrazhenski_Monastery.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Preobrazhenski_Monastery.jpg"}'::text[], 3),
    (v_route, 'Nikopolis ad Istrum', 'Ruiny římského města s dochovaným náměstím a ulicemi severně od Tarnova. Cesta do antiky.', 43.22, 25.61, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nicopolis_ad_Istrum.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nicopolis_ad_Istrum.jpg"}'::text[], 4);
