  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Mys Kaliakra', 'Dlouhý červený útes zabíhající do moře s pevností a legendou o 40 dívkách. Nejdramatičtější místo bulharského pobřeží.', 43.3644, 28.465, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cape_Kaliakra.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cape_Kaliakra.jpg"}'::text[], 0),
    (v_route, 'Palác v Balčiku', 'Romantický rumunský palác královny Marie s botanickou zahradou nad mořem. Idylická zastávka mezi květinami.', 43.4181, 28.16, 'https://commons.wikimedia.org/wiki/Special:FilePath/Balchik_Palace.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Balchik_Palace.jpg"}'::text[], 1),
    (v_route, 'Kavarna', 'Přístavní městečko proslulé rockovými festivaly na útesech nad mořem. Živá zastávka na pobřeží.', 43.4331, 28.34, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kavarna.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kavarna.jpg"}'::text[], 2),
    (v_route, 'Rezervace Jajlata', 'Skalnaté pobřeží s jeskynními obydlími a hnízdišti ptáků. Divoká zastávka pro milovníky přírody.', 43.4344, 28.51, 'https://commons.wikimedia.org/wiki/Special:FilePath/Yailata.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Yailata.jpg"}'::text[], 3),
    (v_route, 'Botanická zahrada Balčik', 'Rozlehlá zahrada s kaktusy a středomořskými rostlinami obklopující palác. Klidné bloudění nad mořem.', 43.4181, 28.16, 'https://commons.wikimedia.org/wiki/Special:FilePath/Balchik_Botanical_Garden.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Balchik_Botanical_Garden.jpg"}'::text[], 4);
