  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Belogradčické skály', 'Fantastické červené skalní věže táhnoucí se kilometry, s pevností vklíněnou mezi útesy. Jeden z divů Bulharska.', 43.625, 22.68, 'https://commons.wikimedia.org/wiki/Special:FilePath/Belogradchik_Rocks.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Belogradchik_Rocks.jpg"}'::text[], 0),
    (v_route, 'Jeskyně Magura', 'Rozlehlá jeskyně s pravěkými nástěnnými malbami netopýřím guánem. Podzemní zážitek severozápadu.', 43.7333, 22.5833, 'https://commons.wikimedia.org/wiki/Special:FilePath/Magura_Cave.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Magura_Cave.jpg"}'::text[], 1),
    (v_route, 'Vračanský Balkán', 'Dramatická vápencová soutěska a jeskyně Ledenika nad městem Vraca. Ráj skalní scenérie.', 43.19, 23.53, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vratsata.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vratsata.jpg"}'::text[], 2),
    (v_route, 'Vodopád Skaklja', 'Sezonní vodopád padající ze skal nad Vracou, jeden z nejvyšších v zemi. Působivá zastávka za deště.', 43.21, 23.55, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vratsa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vratsa.jpg"}'::text[], 3),
    (v_route, 'Pevnost Belogradčik', 'Antická pevnost důmyslně vestavěná mezi skalní věže nad městem. Výhledy do skalního města.', 43.6222, 22.68, 'https://commons.wikimedia.org/wiki/Special:FilePath/Belogradchik_Fortress.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Belogradchik_Fortress.jpg"}'::text[], 4);
