  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Staré město Plovdiv', 'Nejstarší nepřetržitě obývané město Evropy s antickým divadlem a barevnými domy obrození. Kulturní klenot Balkánu.', 42.1486, 24.7517, 'https://commons.wikimedia.org/wiki/Special:FilePath/Plovdiv_Old_Town.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Plovdiv_Old_Town.jpg"}'::text[], 0),
    (v_route, 'Klášter Bačkovo', 'Druhý největší klášter Bulharska s nádhernými freskami v horách jižně od Plovdivu. Duchovní zastávka mezi kopci.', 41.9411, 24.8497, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bachkovo_Monastery.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bachkovo_Monastery.jpg"}'::text[], 1),
    (v_route, 'Asenova pevnost', 'Dramatická středověká pevnost s kostelem na skále nad říčním údolím. Nejfotogeničtější hrad regionu.', 41.985, 24.866, 'https://commons.wikimedia.org/wiki/Special:FilePath/Asen%27s_Fortress.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Asen%27s_Fortress.jpg"}'::text[], 2),
    (v_route, 'Antické divadlo Plovdiv', 'Skvěle zachovalé římské divadlo s výhledem na město, dodnes sloužící představením. Skvost antiky.', 42.1467, 24.7508, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ancient_Theatre_of_Philippopolis.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ancient_Theatre_of_Philippopolis.jpg"}'::text[], 3),
    (v_route, 'Vrch Bunardžik', 'Jeden z pahorků Plovdivu s pomníkem Aljoša a výhledem na město. Klidná zastávka nad střechami.', 42.1494, 24.7375, 'https://commons.wikimedia.org/wiki/Special:FilePath/Plovdiv.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Plovdiv.jpg"}'::text[], 4);
