  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Staré město Sozopol', 'Antické město na skalnatém poloostrově s dřevěnými domy a úzkými uličkami nad mořem. Nejromantičtější letovisko jihu.', 42.4181, 27.6953, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sozopol.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sozopol.jpg"}'::text[], 0),
    (v_route, 'Rezervace Ropotamo', 'Ústí řeky s lužními lesy, lekníny a útesy, ráj ptactva a lodních vyjížděk. Divoká oáza mezi letovisky.', 42.32, 27.72, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ropotamo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ropotamo.jpg"}'::text[], 1),
    (v_route, 'Ahtopol', 'Klidné rybářské městečko na jihu blízko turecké hranice s divokými plážemi. Konec cesty daleko od davů.', 42.1, 27.95, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ahtopol.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ahtopol.jpg"}'::text[], 2),
    (v_route, 'Pláž Djuni', 'Rozlehlá písečná pláž s dunami jižně od Sozopolu. Zastávka na koupání a klid.', 42.35, 27.68, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dyuni.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dyuni.jpg"}'::text[], 3),
    (v_route, 'Nesebar', 'Starobylé město na poloostrově s množstvím byzantských kostelů, UNESCO památka. Klenot severně od Burgasu.', 42.66, 27.73, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nessebar.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nessebar.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Katedrála Alexandra Něvského', 'Monumentální pravoslavná katedrála se zlatými kupolemi, symbol Sofie. Srdce bulharské metropole.', 42.6957, 23.3327, 'https://commons.wikimedia.org/wiki/Special:FilePath/Alexander_Nevsky_Cathedral_Sofia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Alexander_Nevsky_Cathedral_Sofia.jpg"}'::text[], 0),
    (v_route, 'Vitoša – Zlaté mosty', 'Kamenné moře balvanů táhnoucí se svahem hory nad Sofií, oblíbený cíl výletů. Rychlý únik z města do přírody.', 42.635, 23.28, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vitosha.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vitosha.jpg"}'::text[], 1),
    (v_route, 'Boyanský kostel', 'Malý středověký kostel s vynikajícími freskami, UNESCO památka na úpatí Vitoše. Klenot bulharského malířství.', 42.6444, 23.265, 'https://commons.wikimedia.org/wiki/Special:FilePath/Boyana_Church.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Boyana_Church.jpg"}'::text[], 2),
    (v_route, 'Chrám svaté Sofie', 'Starobylý cihlový kostel, podle nějž dostalo město jméno. Klidná zastávka v centru.', 42.6958, 23.3222, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sofia_Church.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sofia_Church.jpg"}'::text[], 3),
    (v_route, 'Cherni Vrah', 'Nejvyšší vrchol Vitoše (2290 m) s výhledem na Sofii a okolní pohoří. Cíl horského výjezdu nad metropolí.', 42.5636, 23.2789, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cherni_Vrah.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cherni_Vrah.jpg"}'::text[], 4);
