-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras — BULHARSKO (10 tras)
-- NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy: is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže dle (name, branch_id).
-- ════════════════════════════════════════════════════════════════════
alter table public.routes add column if not exists countries text[] not null default '{}'::text[];

do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Rilský klášter a hory Rila
  delete from public.routes where name = 'Rilský klášter a hory Rila' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Rilský klášter a hory Rila', 'Okruh nejvyšším pohořím Balkánu k proslulému Rilskému klášteru. Serpentiny mezi štíty, ledovcová jezera a nejposvátnější místo Bulharska nabízí horské zážitky i duchovní klid. Nejlepší od června do září; pozor na horské silnice a mlhy ve výškách.', 'loop', 170, 240, 'medium',
     '[{"lat": 42.1333, "lng": 23.34, "label": "Start: Rilský klášter"}, {"lat": 42.19, "lng": 23.36, "label": "Kirilova poljana"}, {"lat": 42.1789, "lng": 23.3556, "label": "Maljovica"}, {"lat": 42.1333, "lng": 23.34, "label": "Cíl: Rilský klášter"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=42.1333,23.34&destination=42.1333,23.34&travelmode=driving&waypoints=42.19,23.36%7C42.1789,23.3556', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rila_Monastery.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rila_Monastery.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Malyovitsa.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Seven_Rila_Lakes.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Stob_Pyramids.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rila_Monastery.jpg"}'::text[], '{"Rilský klášter","Maljovica","Sedm rilských jezer","Stob – pyramidy","Jeskyně Svatého Ivana"}'::text[], '{"BG"}'::text[], false, 3210, 'approved');

  -- Pirin, Bansko a Melnik
  delete from public.routes where name = 'Pirin, Bansko a Melnik' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Pirin, Bansko a Melnik', 'Trasa jihozápadem Bulharska pod štíty Pirinu k nejmenšímu městu země. Horské Bansko, pískovcové pyramidy Melniku a vinařská tradice nabízí zážitkovou jízdu i skvělé víno. Nejlepší od jara do podzimu; pozor na horské silnice a horko na jihu.', 'poi', 160, 225, 'medium',
     '[{"lat": 41.8375, "lng": 23.4881, "label": "Start: Bansko"}, {"lat": 41.5228, "lng": 23.3931, "label": "Melnik"}, {"lat": 41.53, "lng": 23.43, "label": "Rožen"}, {"lat": 41.8375, "lng": 23.4881, "label": "Cíl: Bansko"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=41.8375,23.4881&destination=41.8375,23.4881&travelmode=driving&waypoints=41.5228,23.3931%7C41.53,23.43', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bansko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bansko.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Melnik.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Melnik_Pyramids.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rozhen_Monastery.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pirin_National_Park.jpg"}'::text[], '{"Bansko","Melnik","Melnické pyramidy","Rožen – klášter","Národní park Pirin"}'::text[], '{"BG"}'::text[], false, 3220, 'approved');

  -- Rodopy a soutěska Trigrad
  delete from public.routes where name = 'Rodopy a soutěska Trigrad' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Rodopy a soutěska Trigrad', 'Náročný okruh divokými Rodopy plnými soutěsek a jeskyní. Dramatická soutěska Trigrad, Ďáblovo hrdlo a horské vesnice nabízí adrenalinovou jízdu a tajuplnou atmosféru. Nejlepší od května do října; pozor na úzké skalní silnice a tunely.', 'loop', 180, 255, 'hard',
     '[{"lat": 41.5764, "lng": 24.7106, "label": "Start: Smoljan"}, {"lat": 41.6144, "lng": 24.3789, "label": "Trigrad"}, {"lat": 41.7431, "lng": 24.4, "label": "Devín"}, {"lat": 41.5764, "lng": 24.7106, "label": "Cíl: Smoljan"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=41.5764,24.7106&destination=41.5764,24.7106&travelmode=driving&waypoints=41.6144,24.3789%7C41.7431,24.4', 'https://commons.wikimedia.org/wiki/Special:FilePath/Trigrad_Gorge.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Trigrad_Gorge.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Smolyan.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Devin.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Devil%27s_Throat_Cave.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Shiroka_Laka.jpg"}'::text[], '{"Soutěska Trigrad","Smoljan","Devín","Ďáblovo hrdlo","Vesnice Široka Laka"}'::text[], '{"BG"}'::text[], false, 3230, 'approved');

  -- Šipka a pohoří Stara planina
  delete from public.routes where name = 'Šipka a pohoří Stara planina' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Šipka a pohoří Stara planina', 'Okruh přes průsmyk Šipka v srdci Balkánu, kde se psaly dějiny Bulharska. Zlatý chrám, památník svobody a bizarní pomník Buzludža nabízí historii i horské výhledy. Nejlepší od května do října; pozor na mlhy v průsmyku.', 'loop', 170, 225, 'medium',
     '[{"lat": 42.62, "lng": 25.3931, "label": "Start: Kazanlak"}, {"lat": 42.7194, "lng": 25.32, "label": "Šipka – chrám"}, {"lat": 42.7357, "lng": 25.3931, "label": "Buzludža"}, {"lat": 42.62, "lng": 25.3931, "label": "Cíl: Kazanlak"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=42.62,25.3931&destination=42.62,25.3931&travelmode=driving&waypoints=42.7194,25.32%7C42.7357,25.3931', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shipka_Memorial_Church.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Shipka_Memorial_Church.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Shipka_Monument.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Buzludzha.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kazanlak.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Etar.jpg"}'::text[], '{"Chrám Šipka","Památník svobody na Šipce","Pomník Buzludža","Kazanlak – Údolí růží","Etar – skanzen"}'::text[], '{"BG"}'::text[], false, 3240, 'approved');

  -- Veliko Tarnovo a středověké památky
  delete from public.routes where name = 'Veliko Tarnovo a středověké památky' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Veliko Tarnovo a středověké památky', 'Okruh kolem bývalé carské metropole Bulharska. Pevnost Carevec nad meandrem řeky, malebné Arbanasi a klidné silnice nabízí koncentraci středověké historie. Nejlepší od jara do podzimu; pozor na turisty ve městě.', 'loop', 140, 195, 'easy',
     '[{"lat": 43.0813, "lng": 25.655, "label": "Start: Veliko Tarnovo"}, {"lat": 43.0778, "lng": 25.67, "label": "Arbanasi"}, {"lat": 43.11, "lng": 25.65, "label": "Preobraženský klášter"}, {"lat": 43.0813, "lng": 25.655, "label": "Cíl: Veliko Tarnovo"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=43.0813,25.655&destination=43.0813,25.655&travelmode=driving&waypoints=43.0778,25.67%7C43.11,25.65', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tsarevets.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tsarevets.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Veliko_Tarnovo.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Arbanasi.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Preobrazhenski_Monastery.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nicopolis_ad_Istrum.jpg"}'::text[], '{"Pevnost Carevec","Staré město Veliko Tarnovo","Arbanasi","Preobraženský klášter","Nikopolis ad Istrum"}'::text[], '{"BG"}'::text[], false, 3250, 'approved');

  -- Severní Černomoří – Kaliakra a Balčik
  delete from public.routes where name = 'Severní Černomoří – Kaliakra a Balčik' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Severní Černomoří – Kaliakra a Balčik', 'Trasa podél severního bulharského pobřeží Černého moře. Červené útesy mysu Kaliakra, romantický palác v Balčiku a stepní rezervace nabízí moře, historii a mírné silnice. Nejlepší od května do září; pozor na letní provoz u letovisek.', 'poi', 150, 195, 'easy',
     '[{"lat": 43.4181, "lng": 28.16, "label": "Start: Balčik"}, {"lat": 43.3644, "lng": 28.46, "label": "Kaliakra"}, {"lat": 43.43, "lng": 28.34, "label": "Kavarna"}, {"lat": 43.4181, "lng": 28.16, "label": "Cíl: Balčik"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=43.4181,28.16&destination=43.4181,28.16&travelmode=driving&waypoints=43.3644,28.46%7C43.43,28.34', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cape_Kaliakra.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cape_Kaliakra.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Balchik_Palace.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kavarna.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Yailata.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Balchik_Botanical_Garden.jpg"}'::text[], '{"Mys Kaliakra","Palác v Balčiku","Kavarna","Rezervace Jajlata","Botanická zahrada Balčik"}'::text[], '{"BG"}'::text[], false, 3260, 'approved');

  -- Belogradčické skály a Vraca
  delete from public.routes where name = 'Belogradčické skály a Vraca' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Belogradčické skály a Vraca', 'Okruh severozápadem Bulharska mezi bizarními skalami a soutěskami. Červené věže Belogradčiku, jeskyně Magura a soutěska Vraca nabízí dramatickou přírodu daleko od davů. Nejlepší od jara do podzimu; pozor na řidší zázemí.', 'loop', 180, 240, 'medium',
     '[{"lat": 43.63, "lng": 22.68, "label": "Start: Belogradčik"}, {"lat": 43.73, "lng": 22.58, "label": "Jeskyně Magura"}, {"lat": 43.21, "lng": 23.55, "label": "Vraca"}, {"lat": 43.63, "lng": 22.68, "label": "Cíl: Belogradčik"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=43.63,22.68&destination=43.63,22.68&travelmode=driving&waypoints=43.73,22.58%7C43.21,23.55', 'https://commons.wikimedia.org/wiki/Special:FilePath/Belogradchik_Rocks.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Belogradchik_Rocks.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Magura_Cave.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vratsata.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vratsa.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Belogradchik_Fortress.jpg"}'::text[], '{"Belogradčické skály","Jeskyně Magura","Vračanský Balkán","Vodopád Skaklja","Pevnost Belogradčik"}'::text[], '{"BG"}'::text[], false, 3270, 'approved');

  -- Plovdiv a klášter Bačkovo
  delete from public.routes where name = 'Plovdiv a klášter Bačkovo' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Plovdiv a klášter Bačkovo', 'Okruh od nejstaršího nepřetržitě obývaného města Evropy k druhému největšímu klášteru Bulharska. Antické památky Plovdivu, freskami zdobené Bačkovo a Rodopské předhůří nabízí kulturu i klidnou jízdu. Nejlepší od jara do podzimu; pozor na provoz v Plovdivu.', 'loop', 150, 195, 'easy',
     '[{"lat": 42.1354, "lng": 24.7453, "label": "Start: Plovdiv"}, {"lat": 41.9411, "lng": 24.8497, "label": "Bačkovo"}, {"lat": 41.98, "lng": 24.86, "label": "Asenova pevnost"}, {"lat": 42.1354, "lng": 24.7453, "label": "Cíl: Plovdiv"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=42.1354,24.7453&destination=42.1354,24.7453&travelmode=driving&waypoints=41.9411,24.8497%7C41.98,24.86', 'https://commons.wikimedia.org/wiki/Special:FilePath/Plovdiv_Old_Town.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Plovdiv_Old_Town.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bachkovo_Monastery.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Asen%27s_Fortress.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ancient_Theatre_of_Philippopolis.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Plovdiv.jpg"}'::text[], '{"Staré město Plovdiv","Klášter Bačkovo","Asenova pevnost","Antické divadlo Plovdiv","Vrch Bunardžik"}'::text[], '{"BG"}'::text[], false, 3280, 'approved');

  -- Sozopol a jižní Černomoří
  delete from public.routes where name = 'Sozopol a jižní Černomoří' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Sozopol a jižní Černomoří', 'Trasa jižním bulharským pobřežím Černého moře. Starobylé Sozopol na poloostrově, přírodní rezervace Ropotamo a písečné pláže nabízí moře, antiku i klid. Nejlepší od května do září; pozor na letní provoz.', 'poi', 130, 180, 'easy',
     '[{"lat": 42.4181, "lng": 27.6953, "label": "Start: Sozopol"}, {"lat": 42.32, "lng": 27.72, "label": "Ropotamo"}, {"lat": 42.1, "lng": 27.95, "label": "Ahtopol"}, {"lat": 42.4181, "lng": 27.6953, "label": "Cíl: Sozopol"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=42.4181,27.6953&destination=42.4181,27.6953&travelmode=driving&waypoints=42.32,27.72%7C42.1,27.95', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sozopol.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sozopol.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ropotamo.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ahtopol.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dyuni.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nessebar.jpg"}'::text[], '{"Staré město Sozopol","Rezervace Ropotamo","Ahtopol","Pláž Djuni","Nesebar"}'::text[], '{"BG"}'::text[], false, 3290, 'approved');

  -- Sofie a hora Vitoša
  delete from public.routes where name = 'Sofie a hora Vitoša' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Sofie a hora Vitoša', 'Okruh od bulharské metropole na horu Vitoša, jež se tyčí přímo nad městem. Katedrála Alexandra Něvského, horské silnice a kamenná moře nabízí kulturu i rychlý únik do přírody. Nejlepší od jara do podzimu; pozor na provoz v Sofii.', 'loop', 120, 165, 'easy',
     '[{"lat": 42.6977, "lng": 23.3219, "label": "Start: Sofie"}, {"lat": 42.635, "lng": 23.28, "label": "Vitoša – Zlaté mosty"}, {"lat": 42.64, "lng": 23.27, "label": "Boyana"}, {"lat": 42.6977, "lng": 23.3219, "label": "Cíl: Sofie"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=42.6977,23.3219&destination=42.6977,23.3219&travelmode=driving&waypoints=42.635,23.28%7C42.64,23.27', 'https://commons.wikimedia.org/wiki/Special:FilePath/Alexander_Nevsky_Cathedral_Sofia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Alexander_Nevsky_Cathedral_Sofia.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vitosha.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Boyana_Church.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sofia_Church.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cherni_Vrah.jpg"}'::text[], '{"Katedrála Alexandra Něvského","Vitoša – Zlaté mosty","Boyanský kostel","Chrám svaté Sofie","Cherni Vrah"}'::text[], '{"BG"}'::text[], false, 3300, 'approved');

end $$;
